import { LoggerService } from '@backstage/backend-plugin-api';
import { ActionsRegistryService } from '@backstage/backend-plugin-api/alpha';
import { SearchEngine } from '@backstage/plugin-search-backend-node';
import { SearchIndexService } from '@backstage/plugin-search-backend-node/alpha';
import { JsonObject } from '@backstage/types';

/**
 * Returns true when the given document location uses a protocol that is safe to
 * expose (http/https), or when it is a relative location with no protocol at
 * all. Locations using other protocols (e.g. `javascript:` or `data:`) are
 * considered unsafe.
 */
const isSafeLocation = (location: unknown): boolean => {
  if (typeof location !== 'string') {
    return true;
  }

  const protocolMatch = /^([a-zA-Z][a-zA-Z0-9+.-]*):/.exec(location);

  // No protocol means a relative location, which is safe.
  if (!protocolMatch) {
    return true;
  }

  const protocol = protocolMatch[1].toLowerCase();
  return protocol === 'http' || protocol === 'https';
};

/**
 * Registers a search query action with the provided actions registry.
 *
 * The action allows agents to query the search engine, forwarding the provided
 * input to {@link SearchEngine.query}. Authorization fields are stripped from
 * the returned documents, and results whose location uses an unsafe protocol
 * are excluded from the output.
 */
export const createQueryAction = ({
  engine,
  actionsRegistry,
  searchIndexService,
  logger,
}: {
  engine: SearchEngine;
  actionsRegistry: ActionsRegistryService;
  searchIndexService: SearchIndexService;
  logger: LoggerService;
}): void => {
  const documentTypes = Object.keys(searchIndexService.getDocumentTypes());
  const typesDescription = documentTypes.length
    ? `Available document types: ${documentTypes.join(', ')}.`
    : 'There are no document types currently indexed.';

  actionsRegistry.register({
    name: 'search',
    title: 'Search',
    attributes: {
      destructive: false,
      readOnly: true,
      idempotent: true,
    },
    description: `
Query the Backstage search engine for documents matching a search term.

${typesDescription}

Results can be narrowed down by document type and filters, and paginated using
the returned \`nextPageCursor\`.
    `,
    schema: {
      input: z =>
        z.object({
          term: z
            .string()
            .describe('The search term to query the search engine with.'),
          types: z
            .array(z.string())
            .optional()
            .describe('Restrict the search to the given document types.'),
          filters: z
            .record(z.any())
            .optional()
            .describe('Filters to apply to the search query.'),
          pageLimit: z
            .number()
            .optional()
            .describe('Maximum number of results to return at a time.'),
          pageCursor: z
            .string()
            .optional()
            .describe(
              'Cursor for pagination, obtained from a previous response.',
            ),
        }),
      output: z =>
        z.object({
          results: z
            .array(
              z.object({
                type: z.string().describe('The type of the document.'),
                document: z
                  .object({
                    title: z.string().describe('The title of the document.'),
                    text: z.string().describe('The text of the document.'),
                    location: z
                      .string()
                      .describe('The location (URL) of the document.'),
                  })
                  .passthrough(),
              }),
            )
            .describe('The list of matching search results.'),
          nextPageCursor: z
            .string()
            .optional()
            .describe('Cursor used to fetch the next page of results.'),
          totalItems: z
            .number()
            .optional()
            .describe('The total number of results matching the query.'),
          hasMoreResults: z
            .boolean()
            .describe('Whether more results are available.'),
        }),
    },
    action: async ({ input }) => {
      const resultSet = await engine.query({
        term: input.term,
        types: input.types,
        filters: input.filters as JsonObject | undefined,
        pageLimit: input.pageLimit,
        pageCursor: input.pageCursor,
      });

      const results = resultSet.results
        .filter(result => {
          if (isSafeLocation(result.document?.location)) {
            return true;
          }

          logger.info(
            `Excluding search result with unsafe location: ${result.document.location}`,
          );
          return false;
        })
        .map(result => {
          const { authorization, ...document } = result.document;
          return {
            type: result.type,
            document,
          };
        });

      return {
        output: {
          results,
          nextPageCursor: resultSet.nextPageCursor,
          totalItems: resultSet.numberOfResults,
          hasMoreResults: !!resultSet.nextPageCursor,
        },
      };
    },
