g).toString());\n}\n\n/**\n * Gets the request options necessary to make requests to a given provider.\n *\n * @param config - The relevant provider config\n * @param token - An optional auth token to use for communicating with GitLab. By default uses the integration token\n * @public\n */\nexport function getGitLabRequestOptions(\n  config: GitLabIntegrationConfig,\n  token?: string,\n): { headers: Record<string, string> } {\n  const headers: Record<string, string> = {};\n\n  const accessToken = token || config.token;\n  if (accessToken) {\n    // OAuth, Personal, Project, and Group access tokens can all be passed via\n    // a bearer authorization header\n    // https://docs.gitlab.com/api/rest/authentication/#personalprojectgroup-access-tokens\n    headers.Authorization = `Bearer ${accessToken}`;\n  }\n\n  return { headers };\n}\n\n// Converts\n// from: https://gitlab.com/groupA/teams/teamA/subgroupA/repoA/-/blob/branch/filepath\n// to:   https://gitlab.com/api/v4/projects/groupA%2Fteams%2FteamA%2FsubgroupA%2FrepoA/repository/files/filepath/raw?ref=branch\nexport function buildProjectUrl(\n  target: string,\n  projectPathOrID: string | Number,\n  config: GitLabIntegrationConfig,\n): URL {\n  try {\n    const url = new URL(target);\n\n    const branchAndFilePath = url.pathname\n      .split('/blob/')\n      .slice(1)\n      .join('/blob/');\n    const [branch, ...filePath] = branchAndFilePath.split('/');\n    const relativePath = getGitLabIntegrationRelativePath(config);\n\n    const projectIdentifier = encodeURIComponent(String(projectPathOrID));\n\n    url.pathname = [\n      ...(relativePath ? [relativePath] : []),\n      'api/v4/projects',\n      projectIdentifier,\n      'repository/files',\n      encodeURIComponent(decodeURIComponent(filePath.join('/'))),\n      'raw',\n    ].join('/');\n\n    url.search = `?ref=${branch}`;\n\n    return url;\n  } catch (e) {\n    throw new Error(`Incorrect url: ${target}, ${e}`);\n  }\n}\n\n/**\n * Extracts the project path from a GitLab URL\n * from: https://gitlab.com/groupA/teams/teamA/subgroupA/repoA/-/blob/branch/filepath\n * to:   groupA/teams/teamA/subgroupA/repoA\n */\nexport function extractProjectPath(\n  target: string,\n  config: GitLabIntegrationConfig,\n): string {\n  const url = new URL(target);\n\n  if (!url.pathname.includes('/blob/')) {\n    throw new Error(\n      `Failed extracting project path from ${url.pathname}. Url path must include /blob/.`,\n    );\n  }\n\n  let repo = url.pathname.split('/-/blob/')[0].split('/blob/')[0];\n\n  // Get gitlab relative path\n  const relativePath = getGitLabIntegrationRelativePath(config);\n\n  // Check relative path exist and replace it if it's the case.\n  if (relativePath) {\n    repo = repo.replace(relativePath, '');\n  }\n\n  // Remove leading slash\n  return repo.replace(/^\\//, '');\n}\n"],"names":["buildProjectUrl","extractProjectPath","getGitLabFileFetchUrl","getGitLabRequestOptions","url","config","_token","projectPath","Promise","resolve","toString","token","headers","accessToken","Authorization","target","projectPathOrID","URL","branchAndFilePath","pathname","split","slice","join","branch","filePath","relativePath","getGitLabIntegrationRelativePath","projectIdentifier","encodeURIComponent","String","decodeURIComponent","search","e","Error","includes","repo","replace"],"mappings":"AAAA;;;;;;;;;;;;;;CAcC;;;;;;;;;;;;;;;;;QA+DeA;eAAAA;;QAuCAC;eAAAA;;QA7EAC;eAAAA;;QAkBAC;eAAAA;;;wBAtCT;AAoBA,SAASD,sBACdE,GAAW,EACXC,MAA+B,EAC/BC,MAAe;IAEf,4EAA4E;IAC5E,0FAA0F;IAC1F,MAAMC,cAAcN,mBAAmBG,KAAKC;IAC5C,OAAOG,QAAQC,OAAO,CAACT,gBAAgBI,KAAKG,aAAaF,QAAQK,QAAQ;AAC3E;AASO,SAASP,wBACdE,MAA+B,EAC/BM,KAAc;IAEd,MAAMC,UAAkC,CAAC;IAEzC,MAAMC,cAAcF,SAASN,OAAOM,KAAK;IACzC,IAAIE,aAAa;QACf,0EAA0E;QAC1E,gCAAgC;QAChC,sFAAsF;QACtFD,QAAQE,aAAa,GAAG,CAAC,OAAO,EAAED,aAAa;IACjD;IAEA,OAAO;QAAED;IAAQ;AACnB;AAKO,SAASZ,gBACde,MAAc,EACdC,eAAgC,EAChCX,MAA+B;IAE/B,IAAI;QACF,MAAMD,MAAM,IAAIa,IAAIF;QAEpB,MAAMG,oBAAoBd,IAAIe,QAAQ,CACnCC,KAAK,CAAC,UACNC,KAAK,CAAC